# -*- coding: utf-8 -*-
"""Нижний блок страницы: домашнее задание и шаблоны промптов (20 штук + промпты практикума), скачивание."""
from lib import card, table, steps, bullets, paras, slide, sec
from prompts import PROMPTS

GROUP_ORDER = ["Подготовка данных", "Шаблоны документов", "Роль в промпте", "Проверка результата"]


def s13() -> str:
    b = slide(23, "Слайд «Итог урока и домашнее задание»: формулы двух пар, четыре пункта домашнего задания, «Подписал — значит проверил»",
              ["Слайд собирает урок в одну картинку: слева — что делать до запроса (пара 1) и после результата (пара 2), справа — домашнее задание. Сфотографируйте его: это ваша шпаргалка на ближайшие недели.",
               "Формула пары 1: задача, необходимые данные, минимизация, обезличивание, проверка настроек, передача в ИИ. Формула пары 2: достоверность, источник, права и согласие, предвзятость и последствия, ответственность. Вместе они образуют цепочку, где решение всегда за человеком."],
              takeaway="Подписал — значит проверил.")
    b += card("Домашнее задание (до следующего занятия)",
              steps(["<b>Паспорт безопасной задачи</b> для двух типов ваших рабочих задач (например, «письмо контрагенту» и «справка руководителю»). Реальных данных не пишите: только тип информации, что нужно ИИ, что убрать, что заменить, где обрабатывать, кто проверит, что вы не знаете и у кого уточните. Бланк — в файлах ниже.",
                     "<b>Пять проверок по одному результату ИИ</b>: возьмите недавний ответ ИИ (или запустите промпт U-справка / U05 на условной теме) и пройдите достоверность, источник, права и согласие, предвзятость и последствия, ответственность. Запишите, что нашли и что исключили.",
                     "<b>Вопросы ответственному</b> по информационной безопасности или юристам предприятия: составьте 5–8 вопросов, на которые не смогли ответить (промпт U18 поможет сформулировать). Ответов на них в уроке нет намеренно: они зависят от локальных актов.",
                     "<b>Один файл</b> без реальных данных: две строки паспорта, результат проверки, список вопросов. Личный чек-лист остаётся у вас."])
              + '<p class="q-hint">Критерии: (1) в паспорте нет реальных данных; (2) указано, кто проверяет результат; (3) неизвестное записано как вопрос, а не как разрешение; (4) в проверке есть хотя бы одно найденное и исключённое утверждение. Необязательное задание: пройдите 15 пунктов личного чек-листа из практикума.</p>')
    b += card("Как пользоваться шаблонами промптов",
              paras(["Все шаблоны построены одинаково: <b>задача</b>, <b>для кого</b>, <b>что известно</b>, <b>что сделать</b>, <b>формат</b>, <b>границы</b>. Всё, что зависит от фактов, стоит в квадратных скобках — заполняете вы, не модель. Роль, если указана, задаёт позицию, формат и тон; проверка фактов остаётся за вами.",
                     "Перед использованием: 1) прочитайте описание промпта; 2) замените поля в скобках условными данными; 3) отправьте в разрешённый инструмент; 4) проверьте результат по пяти проверкам. Для показа на занятии один и тот же промпт отправляйте по очереди в GigaChat, DeepSeek и ChatGPT в новых чатах."]))
    # таблица-каталог всех 20 промптов
    rows = [[p["id"], p["title"], p["group"]] for p in PROMPTS]
    b += table("Каталог: 20 промптов урока", ["№", "Название", "Группа"], rows)
    b += '<div class="deep-bar fade"><span>⌨️ Все 20 промптов</span><b>Копируются целиком одной кнопкой</b></div>'
    for g in GROUP_ORDER:
        items = [p for p in PROMPTS if p["group"] == g]
        if not items:
            continue
        b += f'<h3 class="fade" style="margin:22px 0 8px;font-size:1.05rem">{g}</h3><div class="pk-grid">' + "".join(f"{{{{PK:{p['id']}}}}}" for p in items) + "</div>"
    b += '<p class="q-hint fade">Дополнительно: восемь промптов практикума (кейсы 1–7 и заготовка документа из десяти пунктов) — в разделе «Практикум» выше и в файле промптов. Все данные в промптах условные.</p>'
    b += """<div class="dl-grid fade" style="margin-top:20px">
    <a class="dl" href="../data/urok4/prompty_urok4.docx" download><span class="ico">📝</span><div><b>Промпты урока · DOCX</b><span>20 промптов + 8 промптов практикума</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/prompty_urok4.xlsx" download><span class="ico">📊</span><div><b>Промпты урока · XLSX</b><span>Таблица с группами и описаниями, для менеджера промптов</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/prompty_urok4.txt" download><span class="ico">📄</span><div><b>Промпты урока · TXT</b><span>Одним текстом</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/prompty_urok4.csv" download><span class="ico">🧾</span><div><b>Промпты урока · CSV</b><span>Для импорта</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/prompty_urok4.json" download><span class="ico">🧩</span><div><b>Промпты урока · JSON</b><span>Для разработчиков и менеджеров промптов</span></div><span class="arrow">↓</span></a>
    <a class="dl" href="../data/urok4/domashnee_zadanie_blank.docx" download><span class="ico">📋</span><div><b>Домашнее задание · бланк DOCX</b><span>Два паспорта, проверка результата, вопросы ответственному</span></div><span class="arrow">↓</span></a>
  </div>"""
    return sec("s13", "13", "Домашнее задание и шаблоны промптов",
               "Финальный блок: что сделать после урока и 20 готовых промптов — для повседневных документов, безопасной подготовки данных, роли и проверки результата. Всё можно скачать.", b, "после урока")
